  },
  {
    "voiceText": "The world around may seem dark, but within you lies an unyielding flame.",
    "image_prompt": "A dimly lit room, shadows playing across walls. Close-up of hands lighting a single candle, casting warm light amidst deep shadows."
  },
  {
    "voiceText": "In the silence of despair, your heart whispers the truth of your strength.",
    "image_prompt": "A solitary figure in an empty cafe, rain streaking windows. Soft focus on their reflective expression, city lights blurred behind."
  },
  {
    "voiceText": "Every step feels heavy, yet each one is a testament to your courage.",
    "image_prompt": "Close-up of worn boots stepping through puddles on a gritty urban street, droplets splashing dramatically in the air."
  },
  {
    "voiceText": "You're not alone; every hero has walked this road of trials.",
    "image_prompt": "A series of black and white photos pinned to a wall, each capturing different faces of diverse people in deep thought."
  }
]

